import time
from functools import lru_cache, wraps

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = lru_cache(maxsize=maxsize, typed=typed)
        timestamps = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if typed else args + tuple(kwargs.values())
            current_time = timer()

            if key in timestamps and current_time - timestamps[key] > ttl:
                cache.cache_clear()
                timestamps.pop(key, None)

            if key not in timestamps:
                result = func(*args, **kwargs)
                cache.cache_clear()  # Clear cache to ensure the new result is stored
                cache(*args, **kwargs)  # Store the new result
                timestamps[key] = current_time
                return result

            return cache(*args, **kwargs)

        return wrapper

    return decorator
