def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    from collections import OrderedDict

    def issubclass_tuple(cls, classinfo):
        return any(issubclass(cls, c) for c in classinfo)

    minimal = []
    for cls in classes:
        if not any(issubclass_tuple(cls, minimal)):
            minimal.append(cls)
        else:
            minimal = [c for c in minimal if not issubclass_tuple(c, (cls,))]

    return list(OrderedDict.fromkeys(minimal))
