import re
from typing import Dict, List, Union

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(f"Validation errors: {self.messages}")

def _validate_labels(labels: Dict[Union[str, int, bool], Union[str, list]]):
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    errors = []

    for key, value in labels.items():
        key_str = str(key)
        value_str = str(value)

        if not isinstance(key, (str, int, bool)):
            errors.append({key_str: 'expected string, int, or bool as key'})
        elif not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        if not isinstance(value, (str, list)):
            errors.append({value_str: 'expected string or list as value'})
        elif isinstance(value, list):
            for item in value:
                item_str = str(item)
                if not isinstance(item, str):
                    errors.append({item_str: 'expected string or bytes-like object'})
                elif not value_regex.match(item_str):
                    errors.append({item_str: f"Label value '{item_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})
        elif not value_regex.match(value_str):
            errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9_]+$'"})

    if errors:
        raise ValidationError(errors)
