from typing import AnyStr, Union, Dict, Sequence, Tuple, Any
from collections.abc import Mapping, Sequence

class SQLParams:
    in_style = 'named'  # or 'ordinal'

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if SQLParams.in_style == 'named':
        if not isinstance(params, Mapping):
            raise ValueError("params must be a Mapping for named parameter style")
        out_params = {f":{key}": value for key, value in params.items()}
        formatted_sql = sql
        for key in params:
            formatted_sql = formatted_sql.replace(f":{key}", f":{key}")
        return formatted_sql, out_params
    elif SQLParams.in_style == 'ordinal':
        if not isinstance(params, Sequence):
            raise ValueError("params must be a Sequence for ordinal parameter style")
        out_params = list(params)
        formatted_sql = sql
        for i in range(len(params)):
            formatted_sql = formatted_sql.replace(f"%s", f":{i}", 1)
        return formatted_sql, out_params
    else:
        raise ValueError("Unsupported parameter style")
