from typing import List

class Expression:
    def __init__(self, value):
        self.value = value

    def __and__(self, other):
        return Expression(f"({self.value} & {other.value})")

    def __or__(self, other):
        return Expression(f"({self.value} | {other.value})")

    def __invert__(self):
        return Expression(f"~{self.value}")

    def __eq__(self, other):
        return self.value == other.value

    def __repr__(self):
        return self.value

class Absorber:
    def absorb(self, args: List[Expression]) -> List[Expression]:
        def apply_absorption(expr):
            if isinstance(expr, Expression):
                value = expr.value
                if " & (" in value and " | " in value:
                    a, b = value.split(" & (")
                    b = b.rstrip(")")
                    if a == b.split(" | ")[0]:
                        return Expression(a)
                    if a == b.split(" | ")[1]:
                        return Expression(a)
                if " | (" in value and " & " in value:
                    a, b = value.split(" | (")
                    b = b.rstrip(")")
                    if a == b.split(" & ")[0]:
                        return Expression(a)
                    if a == b.split(" & ")[1]:
                        return Expression(a)
                if " & (~" in value and " | " in value:
                    a, b = value.split(" & (~")
                    b = b.rstrip(")")
                    if a == b.split(" | ")[0]:
                        return Expression(f"{a} & {b.split(' | ')[1]}")
                if " | (~" in value and " & " in value:
                    a, b = value.split(" | (~")
                    b = b.rstrip(")")
                    if a == b.split(" & ")[0]:
                        return Expression(f"{a} | {b.split(' & ')[1]}")
            return expr

        return [apply_absorption(arg) for arg in args]
