from zope.interface import Interface, providedBy, Invalid
from inspect import signature, Parameter
from collections.abc import Iterable

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(getattr(iface, '__methods__', []))
    required_attributes = set(getattr(iface, '__attrs__', []))

    candidate_methods = set(dir(candidate))
    candidate_attributes = {attr for attr in candidate_methods if not callable(getattr(candidate, attr))}

    missing_methods = required_methods - candidate_methods
    missing_attributes = required_attributes - candidate_attributes

    for method in missing_methods:
        errors.append(f"Missing method: {method}")

    for attr in missing_attributes:
        errors.append(f"Missing attribute: {attr}")

    for method in required_methods.intersection(candidate_methods):
        iface_method = getattr(iface, method)
        candidate_method = getattr(candidate, method)
        try:
            iface_sig = signature(iface_method)
            candidate_sig = signature(candidate_method)
            if not _signatures_match(iface_sig, candidate_sig):
                errors.append(f"Method {method} has incorrect signature")
        except ValueError:
            errors.append(f"Method {method} has incorrect signature")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def _signatures_match(iface_sig, candidate_sig):
    iface_params = iface_sig.parameters
    candidate_params = candidate_sig.parameters

    if len(iface_params) != len(candidate_params):
        return False

