import json
from xml.etree import ElementTree
from typing import Dict, Any

def parse_diaspora_webfinger(document: str) -> Dict[str, Any]:
    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            root = ElementTree.fromstring(document)
            data = {}
            for element in root:
                if element.tag.endswith('}subject'):
                    data['subject'] = element.text
                elif element.tag.endswith('}alias'):
                    data['aliases'] = data.get('aliases', []) + [element.text]
                elif element.tag.endswith('}link'):
                    link_data = {}
                    for attr, value in element.attrib.items():
                        link_data[attr] = value
                    data['links'] = data.get('links', []) + [link_data]
            return data
        except ElementTree.ParseError:
            raise ValueError("Document is not in a valid JSON or XRD format")
