import copy

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        for include_key, include_value in parser_dict['include'].items():
            if include_key in parser_dict:
                if isinstance(parser_dict[include_key], dict) and isinstance(include_value, dict):
                    parser_dict[include_key] = {**copy.deepcopy(include_value), **parser_dict[include_key]}
                elif isinstance(parser_dict[include_key], list) and isinstance(include_value, list):
                    parser_dict[include_key] = include_value + parser_dict[include_key]
                else:
                    parser_dict[include_key] = include_value
            else:
                parser_dict[include_key] = copy.deepcopy(include_value)
        del parser_dict['include']
